public sealed class CreateUserRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100, MinimumLength = 2)]
    public string Name { get; set; } = string.Empty;

    [Range(18, 120, ErrorMessage = "Age must be between 18 and 120.")]
    public int Age { get; set; }

    [Required]
    [EmailAddress]
    public string Email { get; set; } = string.Empty;
}

[HttpPost]
public IActionResult Create(CreateUserRequest request)
{
    if (!ModelState.IsValid)
    {
        return ValidationProblem(ModelState);
    }

    // Persist and return success
    return CreatedAtAction(nameof(GetById), new { id = 1 }, request);
}

public sealed class StartsWithAttribute : ValidationAttribute
{
    private readonly string _prefix;

    public StartsWithAttribute(string prefix)
    {
        _prefix = prefix;
    }

    public override bool IsValid(object? value)
    {
        if (value is null)
        {
            return true; // let [Required] handle null
        }

        var text = value.ToString();
        return text is not null && text.StartsWith(_prefix, StringComparison.Ordinal);
    }
}
